sp_widget.client_script:
api.controller = function($location) {
  var c = this;
  c.modal = { show: false };

  c.checkLoginAndRedirect = function(event, url) {
    event.preventDefault();

    if (!c.data.isLoggedIn) {
      // Not logged in -> Show Authentication Modal
      c.modal = {
        show: true,
        title: 'Authentication Required',
        message: 'You are not logged in. Please log in first to access the dashboard.',
        confirmLabel: 'Okay',
        confirmAction: function() { c.modal.show = false; }
      };
    } else if (!c.data.hasAwardRole) {
      // Logged in but missing role -> Show Restricted Modal
      c.modal = {
        show: true,
        title: 'Access Restricted',
        message: 'Your application hasn\'t been awarded a grant yet. Once you\'re awarded, you\'ll be able to access the dashboard.',
        confirmLabel: 'Okay',
        confirmAction: function() { c.modal.show = false; }
      };
    } else {
      // Logged in and has role -> Go straight to the dashboard
      $location.href = url;
    }
  };
};

sp_widget.css:
/* =========================================================
   GATENOW LANDING · FOOTER
   Service Portal widget · CSS / SCSS

   Selectors are written out in full. The Service Portal Sass
   compiler does not support parent selector concatenation.

   Design notes worth keeping:

   1. Light, not dark. A dark footer would be the only dark
      block on a page built entirely from pale blue and white,
      and it would read as a different site rather than the end
      of this one. The pale blue closes the page on the same
      tone the hero opened it with.

   2. Two rules and nothing else. The page has already used
      panels, sheets and grids, so the last thing anyone needs
      is a footer with four columns of links pretending to be a
      site map.

   3. Every link underlines itself from the left on hover. It is
      the same movement used on links in the FAQ and closing
      sections, so the page keeps one idea of what a link does.

   4. Nothing is held at opacity zero in a base rule. The
      from-state comes from animation-fill-mode backwards, so if
      animation is blocked the content still renders.
   ========================================================= */

/* ---------- typeface ----------
   Shared with the other landing widgets. If they sit on one
   page, keep a single copy in a Style Sheet record attached to
   the theme and delete this block from the widgets.
   ------------------------------------------------------------- */

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_regular.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 500;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_medium.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 600;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_semibold.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 700;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_bold.woff2") format("woff2");
}


/* ---------- palette ---------- */
$gnt-navy:    #0a2540;
$gnt-blue:    #1560e0;
$gnt-blue-dk: #0f4cbb;
$gnt-body:    #55677f;
$gnt-hair:    #dfe7f3;

$gnt-ease:    cubic-bezier(0.45, 0.05, 0.25, 1);

$gnt-font: "Outfit", "Segoe UI", Roboto, -apple-system, BlinkMacSystemFont, "Helvetica Neue", Arial, sans-serif;


/* =========================================================
   BAND
   ========================================================= */

.gnt-foot {
  position: relative;
  width: 100%;
  padding: 58px 24px 46px;
  font-family: $gnt-font;
  color: $gnt-navy;
  background: linear-gradient(180deg, #ffffff 0%, #f3f8fe 46%, #eaf2fd 100%);
  border-top: 1px solid $gnt-hair;
}

.gnt-foot *,
.gnt-foot *::before,
.gnt-foot *::after { box-sizing: border-box; }

.gnt-foot__inner {
  position: relative;
  max-width: 1140px;
  margin: 0 auto;
}


/* =========================================================
   TOP LINE
   ========================================================= */

.gnt-top {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 26px 40px;
  padding-bottom: 30px;
  border-bottom: 1px solid $gnt-hair;
}

.gnt-brand { min-width: 0; }

.gnt-mark {
  display: inline-flex;
  align-items: center;
  text-decoration: none;
  opacity: 0.92;
  transition: opacity 0.55s $gnt-ease, transform 0.55s $gnt-ease;
}

.gnt-mark:hover,
.gnt-mark:focus {
  text-decoration: none;
  opacity: 1;
  transform: translateY(-1px);
}

/* the lockup is roughly five and a half to one, so height is
   the only dimension worth setting */
.gnt-foot .gnt-mark .gnt-mark__img {
  display: block;
  height: 30px;
  width: auto;
  max-width: 100%;
}

/* -------------------------------------------------------------
   Logo recolouring, defensive rules

   Portal footer styling commonly runs brightness(0) invert(1) on
   logo images, on the assumption that every footer is dark.
   Against a blue lockup that produces a white one.

   The important flags are deliberate. A theme rule that sets a
   filter almost always sets it with !important, and specificity
   alone will not beat that.

   Note the second rule. A filter on an ancestor is applied after
   its whole subtree has rendered, so a child cannot undo it.
   brightness(0) destroys the colour before the child rule is
   ever consulted. That is why the reset has to cover the section
   and everything inside it, not just the image.
   ------------------------------------------------------------- */

.gnt-foot,
.gnt-foot .gnt-brand,
.gnt-foot .gnt-mark {
  filter: none !important;
  -webkit-filter: none !important;
  mix-blend-mode: normal !important;
}

.gnt-foot .gnt-mark .gnt-mark__img {
  filter: none !important;
  -webkit-filter: none !important;
  mix-blend-mode: normal !important;
  opacity: 1 !important;
  background: transparent !important;

  /* isolation creates a new stacking context, which stops a
     blend mode set further up the tree reaching this element */
  isolation: isolate;
}

/* typed fallback, used only when no logo record is set */
.gnt-mark__type {
  display: inline-flex;
  align-items: baseline;
  font-size: 25px;
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.035em;
}

.gnt-mark__a { color: $gnt-navy; }

/* the same trick as the hero, where the second half of the
   phrase carries the colour */
.gnt-mark__b {
  color: $gnt-blue;
  transition: color 0.55s $gnt-ease;
}

.gnt-mark:hover .gnt-mark__b { color: $gnt-blue-dk; }

.gnt-foot .gnt-brand__line {
  margin: 12px 0 0;
  padding: 0;
  max-width: 360px;
  font-size: 15.5px;
  font-weight: 400;
  line-height: 1.6;
  color: $gnt-body;
}


/* ---------- navigation ---------- */

.gnt-nav {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px 32px;
}

.gnt-nav__link {
  position: relative;
  display: inline-flex;
  align-items: center;
  padding: 2px 0 5px;
  color: $gnt-navy;
  font-size: 15.5px;
  font-weight: 500;
  letter-spacing: -0.01em;
  text-decoration: none;
  transition: color 0.55s $gnt-ease;
}

.gnt-nav__link:hover,
.gnt-nav__link:focus {
  color: $gnt-blue-dk;
  text-decoration: none;
}

.gnt-nav__rule {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  height: 1px;
  background: currentColor;
  transform: scaleX(0);
  transform-origin: left center;
  transition: transform 0.55s $gnt-ease;
}

.gnt-nav__link:hover .gnt-nav__rule,
.gnt-nav__link:focus .gnt-nav__rule { transform: scaleX(1); }


/* =========================================================
   BASE LINE
   ========================================================= */

.gnt-base {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px 32px;
  padding-top: 26px;
}

.gnt-foot .gnt-base__note {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  margin: 0;
  padding: 0;
  font-size: 14px;
  color: rgba(85, 103, 127, 0.86);
}

.gnt-base__copy { color: $gnt-body; }

.gnt-base__dot {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: rgba(21, 96, 224, 0.35);
  flex-shrink: 0;
}

.gnt-base__made { color: rgba(85, 103, 127, 0.78); }

.gnt-foot .gnt-legal {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px 26px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.gnt-legal__link {
  position: relative;
  display: inline-flex;
  padding: 2px 0 4px;
  color: rgba(85, 103, 127, 0.86);
  font-size: 14px;
  font-weight: 500;
  text-decoration: none;
  transition: color 0.55s $gnt-ease;
}

.gnt-legal__link:hover,
.gnt-legal__link:focus {
  color: $gnt-blue-dk;
  text-decoration: none;
}

.gnt-legal__rule {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  height: 1px;
  background: currentColor;
  transform: scaleX(0);
  transform-origin: left center;
  transition: transform 0.55s $gnt-ease;
}

.gnt-legal__link:hover .gnt-legal__rule,
.gnt-legal__link:focus .gnt-legal__rule { transform: scaleX(1); }

.gnt-foot a:focus-visible {
  outline: 2px solid $gnt-blue;
  outline-offset: 4px;
  border-radius: 4px;
}


/* =========================================================
   MOTION
   Restrained on purpose. A footer that performs on arrival is
   a footer competing with the thing above it.
   ========================================================= */

@media (prefers-reduced-motion: no-preference) {

  @keyframes gntRise {
    from { opacity: 0; transform: translateY(12px); }
    to   { opacity: 1; transform: translateY(0); }
  }

  .gnt-brand,
  .gnt-nav__link,
  .gnt-base {
    animation: gntRise 0.6s $gnt-ease backwards;
  }

  .gnt-nav__link--1 { animation-delay: 0.06s; }
  .gnt-nav__link--2 { animation-delay: 0.11s; }
  .gnt-nav__link--3 { animation-delay: 0.16s; }
  .gnt-nav__link--4 { animation-delay: 0.21s; }

  .gnt-base { animation-delay: 0.26s; }
}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 900px) {

  .gnt-foot { padding: 48px 20px 40px; }

  .gnt-top {
    align-items: flex-start;
    gap: 22px;
  }

  .gnt-nav { gap: 10px 26px; }
}

@media (max-width: 620px) {

  .gnt-foot { padding: 40px 16px 34px; }

  .gnt-top {
    flex-direction: column;
    gap: 24px;
    padding-bottom: 24px;
  }

  .gnt-base {
    flex-direction: column;
    align-items: flex-start;
    gap: 16px;
    padding-top: 22px;
  }

  /* stacked, so the separator between the two notes turns into
     a line break rather than a dot */
  .gnt-foot .gnt-base__note {
    flex-direction: column;
    align-items: flex-start;
    gap: 6px;
  }

  .gnt-base__dot { display: none; }

  .gnt-foot .gnt-mark .gnt-mark__img { height: 26px; }
  .gnt-mark__type { font-size: 23px; }
  .gnt-foot .gnt-brand__line { font-size: 15px; }
}

@media (prefers-reduced-motion: reduce) {
  .gnt-foot * { transition: none; }
  .gnt-mark:hover { transform: none; }
}

/* =========================================================
   MODAL STYLES (Appended from Hero)
   ========================================================= */

.gn-modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(10, 37, 64, 0.55);
  backdrop-filter: blur(4px);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 9999;
  padding: 20px;
  animation: gnFadeIn 0.2s ease-out;
}

.gn-modal {
  position: relative;
  width: 100%;
  max-width: 400px;
  background: #ffffff;
  border-radius: 24px;
  padding: 44px 38px 36px;
  text-align: center;
  font-family: $gnt-font;
  box-shadow: 0 30px 60px rgba(10, 37, 64, 0.22);
  animation: gnPopIn 0.24s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.gn-modal-title {
  margin: 0 0 10px;
  font-size: 24px;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: $gnt-navy;
}

.gn-modal-message {
  margin: 0 0 30px;
  font-size: 15.5px;
  font-weight: 400;
  line-height: 1.55;
  letter-spacing: -0.005em;
  color: $gnt-body;
}

.gn-modal-actions {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.gn-btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 56px;
  padding: 0 32px;
  border: none;
  border-radius: 999px;
  background: $gnt-blue;
  color: #ffffff;
  font-family: $gnt-font;
  font-size: 16px;
  font-weight: 600;
  letter-spacing: -0.01em;
  cursor: pointer;
  box-shadow: 0 14px 30px rgba(21, 96, 224, 0.30);
  transition: background 0.22s ease, box-shadow 0.22s ease, transform 0.22s ease;
}

.gn-btn-primary:hover {
  background: $gnt-blue-dk;
  box-shadow: 0 18px 38px rgba(21, 96, 224, 0.38);
  transform: translateY(-2px);
}

.gn-btn-text {
  background: none;
  border: none;
  padding: 6px;
  font-family: $gnt-font;
  font-size: 14px;
  font-weight: 500;
  color: $gnt-body;
  cursor: pointer;
  transition: color 0.18s ease;
}

.gn-btn-text:hover {
  color: $gnt-navy;
}

.gn-modal-close {
  position: absolute;
  top: 18px;
  right: 18px;
  width: 32px;
  height: 32px;
  border: none;
  background: none;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: $gnt-body;
  cursor: pointer;
  transition: background 0.18s ease, color 0.18s ease;
}

.gn-modal-close:hover {
  background: #e8f0fe;
  color: $gnt-navy;
}

@keyframes gnFadeIn {
  from { opacity: 0; }
  to   { opacity: 1; }
}

@keyframes gnPopIn {
  from { opacity: 0; transform: scale(0.92) translateY(10px); }
  to   { opacity: 1; transform: scale(1) translateY(0); }
}

@media (max-width: 620px) {
  .gn-modal {
    padding: 36px 26px 28px;
    border-radius: 20px;
  }
  .gn-modal-title { font-size: 21px; }
  .gn-modal-message { font-size: 14.5px; }
  .gn-btn-primary { height: 52px; font-size: 15px; }
}

@media (prefers-reduced-motion: reduce) {
  .gn-modal-overlay,
  .gn-modal { animation: none; }
}

sp_widget.script:
(function () {
  function opt(name, fallback) {
    var value = options[name];
    if (value === null || value === undefined || value === '') {
      return fallback;
    }
    return value.toString();
  }

  var LOGO = 'x_enno_gatenow.GateNow%20Logo.png';
  data.logoUrl = opt('logo_url', LOGO);
  data.logoAlt = opt('logo_alt', 'GateNow');
  data.markLead = opt('mark_lead', 'Gate');
  data.markTail = opt('mark_tail', 'Now');

  var portalHomepage = 'x_enno_gatenow_landing'; 
  var applicantDashboardPage = 'applicant_dashboard';

  data.homeUrl = opt('home_url', '?id=' + portalHomepage);
  data.tagline = opt('tagline', gs.getMessage('Apply, report and get paid in one place.'));
  data.navLabel = opt('nav_label', gs.getMessage('Footer navigation'));

  /* =========================================================
     ACCESS CONTROL CHECK
     ========================================================= */
  data.isLoggedIn = gs.getSession().isLoggedIn();
  data.hasAwardRole = false;

  if (data.isLoggedIn) {
    var gr = new GlideRecordSecure('sys_user_has_role');
    gr.addQuery('user', gs.getUserID());
    gr.addQuery('role.name', 'x_enno_gatenow.grant_awards_user');
    gr.query();
    if (gr.next()) {
      data.hasAwardRole = true;
    }
  }

  var dashboardUrl = opt('dashboard_url', '?id=' + applicantDashboardPage);

  /* =========================================================
     FOOTER LINKS
     ========================================================= */
  data.links = [
    {
      label: gs.getMessage('Programs'),
      url: opt('programs_url', '?id=opportunities')
    },
    {
      label: gs.getMessage('How it works'),
      url: opt('process_url', '#how-applying-works')
    },
    {
      label: gs.getMessage('Dashboard'),
      url: dashboardUrl,
      isDashboard: true // Flag to trigger custom click logic in HTML
    }
  ];

  var year = new GlideDateTime().getYearLocalTime();
  data.copyright = opt('copyright', '\u00A9 ' + year + ' GateNow');
  data.madeFor = opt('made_for', gs.getMessage('Made for the people who write the bids.'));

  data.legal = [
    {
      label: gs.getMessage('Privacy Policy'),
      url: opt('privacy_url', '?id=privacy_policy')
    }
  ];
})();
